entries[260172] = { ["name"] = "Apfelschimmel", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Apfelschimmel der Sturmwacht oder gibt ihn wieder frei.\n\"Ein beliebtes Reittier bei den Meerespriestern, die in Sturmsang beheimatet sind.\"\nVerkäufer:\nSchwester Liliana\nZone:\nDas Sturmsangtal\nDie Sturmwacht - Ehrfürchtig\nKosten:\n10.000" }
entries[260173] = { ["name"] = "Nebelgraues Streitross", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer rußschwarzes Kronsteigstreitross oder gibt es wieder frei.\n\"Diese Rösser gehören zu den ältesten Pferderassen in Kul Tiras und sind sogar viele Male im ersten Kampf gegen die Drust vorangestürmt.\"\nVerkäufer:\nRüstmeister Alkorn\nZone:\nDrustvar\nDer Glutorden - Ehrfürchtig\nKosten:\n10.000" }
entries[260174] = { ["name"] = "Verängstigtes Packmuli", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer verängstigtes Packmuli oder gibt es wieder frei.\n\"Dieses arme Muli befand sich in Drustvar, als die Hexen dort die Herrschaft an sich rissen. Es hat schon zu viel miterlebt.\"\nZone:\nDrustvar" }
entries[260175] = { ["name"] = "Goldmähne", ["text"] = "Wirken in 1.5 sek.\nBeschwört Goldmähne oder gibt ihn wieder frei.\n\"Lord Sturmsang befahl seinen Handlangern, dieses Pferd vom Anwesen der Norwinsens in Tiragarde zu stehlen, da er seine herrliche goldene Mähne begehrte.\"\nZone:\nSturmsangtal" }
